export const GEORGIA_COUNTY_BY_ID: Record<string, GeorgiaCounty> = Object.fromEntries(
  GEORGIA_COUNTIES.map((c) => [c.id, c]),
);

export const METRO_ATLANTA_IDS = ["fulton", "henry", "cobb", "dekalb"] as const;

export function resolveCountyIds(input?: string[] | null): string[] {
  if (!input || input.length === 0) return [...METRO_ATLANTA_IDS];
  if (input.includes("all")) return GEORGIA_COUNTIES.map((c) => c.id);
  if (input.includes("metro")) return [...METRO_ATLANTA_IDS];
  if (input.includes("live")) {
    return GEORGIA_COUNTIES.filter((c) => c.collector !== "directory").map((c) => c.id);
  }
  const ids = [...new Set(input.map((x) => x.toLowerCase().trim()).filter(Boolean))];
  return ids.filter((id) => GEORGIA_COUNTY_BY_ID[id]);
}

